# ==============================================================================
# 05_descriptive_figures.R
#
#   - Figure 2: illustrative ZVL effect vs. age-related cognitive decline
#
# (Figure S1 "vaccination uptake over time" and the observed-follow-up
# figure are generated by R/24_descriptive_figures_S1_S42.R, which matches
# the published chart type/style; this script owns Figure 2 only.)
# ==============================================================================
suppressPackageStartupMessages({ library(dplyr); library(ggplot2) })
source("R/01_event_study_utils.R")

panel <- readRDS("data/analysis_panel.rds")
dir.create("output/figures", recursive = TRUE, showWarnings = FALSE)
dir.create("output/tables", recursive = TRUE, showWarnings = FALSE)

# ------------------------------------------------------------------------
# Figure 2: illustrative ZVL effect vs. expected age-related decline
#
# Population age-related decline curve: mean CASI Total Score by visit age
# among ZVL-vaccinated individuals ("Trajectory without ZVL", the
# counterfactual continuation of the pre-vaccination trend).
# ZVL effect: primary event-study post-vaccination coefficients (Figure 1),
# added on top of the age trajectory starting at the mean vaccination age
# (illustrated at age 75, close to this cohort's mean vaccination age), to
# form "Trajectory with ZVL". Matches the published Figure 2 style: both
# series in black, distinguished by linetype (solid = with ZVL, dotted =
# without ZVL), with a red dashed reference line at the vaccination age.
# ------------------------------------------------------------------------
primary <- panel %>%
  filter(!is.na(zost1_date), !is.na(casi_total)) %>%
  build_event_time("zost1_date")

age_curve <- primary %>%
  mutate(age_bin = round(visit_age)) %>%
  filter(age_bin >= 65, age_bin <= 90) %>%
  group_by(age_bin) %>%
  summarise(mean_casi = mean(casi_total, na.rm = TRUE), .groups = "drop")

mean_vax_age_val <- primary %>%
  distinct(subject, zost1_date) %>%
  left_join(panel %>% group_by(subject) %>% summarise(baseline_date = min(visit_date), b_age = min(visit_age)), by = "subject") %>%
  mutate(vax_age = b_age + as.numeric(zost1_date - baseline_date) / 365.25) %>%
  summarise(m = mean(vax_age, na.rm = TRUE)) %>% pull(m)
cat(sprintf("Mean ZVL vaccination age: %.1f  (paper: 78.2)\n", mean_vax_age_val))

es_res <- run_event_study(primary, "casi_total")
es_tbl <- es_table(es_res$mod)

vax_illustration_age <- 75
post <- es_tbl %>% filter(grepl("^trt_p", term)) %>%
  mutate(years_after = as.numeric(sub("trt_p", "", term)) * 2,
         age = vax_illustration_age + years_after)

age_fun <- approxfun(age_curve$age_bin, age_curve$mean_casi, rule = 2)
post <- post %>% mutate(age_curve_value = age_fun(age),
                         illustrative_casi = age_curve_value + estimate,
                         illustrative_lo = age_curve_value + ci_low,
                         illustrative_hi = age_curve_value + ci_high)

without_zvl <- age_curve %>% transmute(age = age_bin, casi = mean_casi, series = "Trajectory without ZVL")
with_zvl <- bind_rows(
  age_curve %>% filter(age_bin <= vax_illustration_age) %>% transmute(age = age_bin, casi = mean_casi),
  post %>% transmute(age, casi = illustrative_casi)
) %>% mutate(series = "Trajectory with ZVL")
ribbon_df <- post %>% transmute(age, ymin = illustrative_lo, ymax = illustrative_hi)

traj <- bind_rows(without_zvl, with_zvl) %>%
  mutate(series = factor(series, levels = c("Trajectory with ZVL", "Trajectory without ZVL")))

p3 <- ggplot() +
  geom_ribbon(data = ribbon_df, aes(x = age, ymin = ymin, ymax = ymax), fill = "grey70", alpha = 0.3) +
  geom_line(data = traj, aes(x = age, y = casi, linetype = series), color = "black", linewidth = 0.6) +
  geom_vline(xintercept = vax_illustration_age, linetype = "dashed", color = "red") +
  annotate("text", x = vax_illustration_age + 0.5, y = max(traj$casi), label = "ZVL vaccination",
           hjust = 0, vjust = 1, size = 3.5) +
  scale_linetype_manual(values = c("Trajectory with ZVL" = "solid", "Trajectory without ZVL" = "dotted")) +
  labs(x = "Age (years)", y = "CASI Total Score", linetype = NULL, title = NULL) +
  theme_minimal() +
  theme(legend.position = "top")
ggsave("output/figures/Figure2_illustrative_trajectory.png", p3, width = 7.5, height = 5.5, dpi = 300)
readr::write_csv(bind_rows(without_zvl, with_zvl), "output/tables/Figure2_illustrative_data.csv")

cat("\nSaved Figure 2 (illustrative trajectory)\n")
